public static Class[] resolveArguments(Type genericType, Class<?> targetType) {
    Class<?>[] parameterizedTypes = null;

    if (genericType instanceof ParameterizedType) {
        ParameterizedType parameterizedType = (ParameterizedType) genericType;
        Type[] arguments = parameterizedType.getActualTypeArguments();

        if (arguments != null && arguments.length > 0) {
            // Check if the type variable is from the target type
            Type[] typeParameters = targetType.getTypeParameters();
            if (typeParameters != null && typeParameters.length > 0) {
                parameterizedTypes = new Class[arguments.length];
                for (int i = 0; i < arguments.length; i++) {
                    Type argument = arguments[i];
                    if (argument instanceof Class) {
                        parameterizedTypes[i] = (Class) argument;
                    } else if (argument instanceof TypeVariable) {
                        String typeVariableName = ((TypeVariable) argument).getName();
                        for (int j = 0; j < typeParameters.length; j++) {
                            if (typeParameters[j].getName().equals(typeVariableName)) {
                                parameterizedTypes[i] = (Class) typeParameters[j];
                                break;
                            }
                        }
                    }
                }
            }
        }
    }

    return parameterizedTypes;
}

