    Map<String, Object> content = new HashMap<>();
    jsonObject.entrySet().forEach(entry -> {
        String key = entry.getKey();
        Object value = entry.getValue();
        // if the value is a JsonObject, recursively call buildContent
        if (value instanceof JsonObject) {
            content.put(key, buildContent((JsonObject) value));
        } else if (value instanceof JsonArray) {
            // if the value is a JsonArray, iterate over the elements and call buildContent
            for (int i = 0; i < ((JsonArray) value).size(); i++) {
                JsonElement element = ((JsonArray) value).get(i);
                // if the element is a JsonObject, call buildContent recursively
                if (element instanceof JsonObject) {
                    content.put(key + "[" + i + "]", buildContent((JsonObject) element));
                } else {
                    content.put(key + "[" + i + "]", element);
                }
            }
        } else {
            content.put(key, value);
        }
    });
    return content;
