/**
 * Puts an array of bytes into this byte vector. The byte vector is automatically enlarged if necessary.
 * @param byteArrayValue an array of bytes. May be {@code null} to put {@code byteLength} nullbytes into this byte vector.
 * @param byteOffset     index of the first byte of byteArrayValue that must be copied.
 * @param byteLength     number of bytes of byteArrayValue that must be copied.
 * @return this byte vector.
 */
public ByteVector putByteArray(byte[] byteArrayValue, int byteOffset, int byteLength) {
    // Check for null array
    if (byteArrayValue == null) {
        byteArrayValue = new byte[byteLength];
        java.util.Arrays.fill(byteArrayValue, (byte) 0);
    }

    // Check bounds
    if (byteOffset < 0 || byteOffset + byteLength > byteArrayValue.length) {
        throw new IndexOutOfBoundsException("Invalid byte array range: [" + byteOffset + "," + byteOffset + byteLength + ")");
    }

    // Allocate more space if needed
    ensureCapacity(byteLength);

    // Copy array
    System.arraycopy(byteArrayValue, byteOffset, bytes, count, byteLength);

    // Update count
    count += byteLength;

    return this;
}

