private int findUpperBound(K key, int n) {

    // initialize the lower and upper bounds of the search range
    int lo = 0;
    int hi = n;

    // loop until the upper bound is found
    while (lo <= hi) {

        // compute the middle index of the search range
        int mid = lo + (hi - lo) / 2;

        // if the middle index is greater than the key, the upper bound is in the lower half of the search range
        if (keys.get(mid) > key) {
